source(file.path("r","addestra_modelli.R")); set.seed(1); d<-data.frame(dateGame=as.Date("2026-01-01")+0:39,minutes=rnorm(40),pts=rnorm(40),treb=rnorm(40),ast=rnorm(40),pts_ast=rnorm(40),pts_treb=rnorm(40),treb_ast=rnorm(40),x=rnorm(40),exp_min_q30=1,exp_min_sd=1,exp_pts_q30=1,exp_treb_q30=1,exp_ast_q30=1); l<-setNames(replicate(7,"x",simplify=FALSE),sequenza_target_nba()); z<-configura_sequenza_modelli(d,l); o<-genera_oof_temporali_nba(d,d$dateGame,"minutes","x",list(num.trees=10L,mtry=1L,min.node.size=2L,sample.fraction=.8),n_folds=3L); stopifnot(verifica_audit_oof(o$audit)); cfg<-configurazione_fasce_q30_nba("minutes"); cal<-calibra_q30_per_fasce_nba(c(10, 20, 30), c(10, 20, 30), cfg); stopifnot(nrow(cal)==3L, identical(applica_q30_per_fasce_nba(c(10, 20, 30),cal,cfg),c(10,20,30))); fit<-addestra_target_ranger_nba(z$dati,"minutes","x",list(num.trees=10L,mtry=1L,min.node.size=2L,sample.fraction=.8)); stopifnot(nrow(fit$calibrazione_q30_fasce_validation)==3L); d2<-z$dati; d2$exp_min_q30[1:5]<-NA; fit2<-addestra_target_ranger_nba(d2,"pts",c("x","exp_min_q30"),list(num.trees=10L,mtry=1L,min.node.size=2L,sample.fraction=.8)); meta2<-calibra_meta_oof_nba(d2$pts[fit2$indici$train],fit2$oof_raw,d2$dateGame[fit2$indici$train]); d2<-aggiungi_meta_feature_nba(d2,"pts",meta2$q30,fit2$q30_validation,fit2$q30_test,indici=fit2$indici); esclusi2<-setdiff(seq_len(nrow(d2)),unlist(fit2$indici)); stopifnot(all(is.na(d2$exp_pts_q30[esclusi2])),all(is.finite(d2$exp_pts_q30[fit2$indici$validation])),all(is.finite(d2$exp_pts_q30[fit2$indici$test]))); s<-addestra_sequenza_ranger_nba(d,l,list(num.trees=10L,mtry=1L,min.node.size=2L,sample.fraction=.8)); stopifnot(length(s$modelli)==7,"exp_min_q30"%in%names(s$dati)); cat("test_addestra_modelli: OK\n")
